    })
    .pipe(
      Effect.retry({
        while: (e): boolean =>
          e._tag === "DeploymentConfigInUseException",
        schedule: Schedule.max([
          Schedule.fixed(3000),
          Schedule.recurs(10),
        ]),
      }),
    );
